@js:
var url = source.key;
var result = [];
var push = (title, url, type) => result.push({
  title: title,
  url: url,
  style: {
    layout_flexGrow: 1,
    layout_flexBasisPercent: type
  }
});

var a = org.jsoup.Jsoup.parse(java.ajax(source.key + "/xclass/0/1.html"));
var b = org.jsoup.Jsoup.parse(java.ajax(source.key + "/quanben.html"));
var c = org.jsoup.Jsoup.parse(java.ajax(source.key + "/ph/week.html"));

java.toast("😜正在刷新分类数据...");
push("🔥全部分类🔥", null, 1);
var lis = a.select(".sortChannel_nav a");    
for (var i = 0; i < lis.length; i++) {
    var text =String( lis[i].select('a').text()).replace(/\s+/g, " "); 
    var href = url +String( lis[i].select('a').attr('href')).replace(/\d+\.html$/,"") + "{{page}}.html";
    push(text, href, 0.33);
}

push("🔥全本小说🔥", null, 1);
var lis = b.select(".sortChannel_nav a");
for (var i = 0; i < lis.length; i++) {
    var text = lis[i].select('a').text();
    var href = url + String(lis[i].select('a').attr('href')).replace(/.html$/, "") + "_{{page}}.html";
    push(text, href, 0.33);
}

push("🔥排行榜单🔥", null, 1);
var lis = c.select(".sortChannel_nav a");
for (var i = 0; i < lis.length; i++) {
    var text = lis[i].select('a').text();
    var href = url + String(lis[i].select('a').attr('href')).replace(/.html$/, "") + "_{{page}}.html";
    push(text, href, 0.33);
}
java.toast("🤔分类数据刷新完成！");
JSON.stringify(result);

